    @can('changeTask', $dossier)@if($task->assigned_to === auth()->id() || auth()->user()->checkPermissionTo('workspace.manage_tasks', 'web'))<form method="POST" action="{{ route('workspace.tasks.update', [$dossier, $task]) }}" class="ws-task-form">@csrf @method('PATCH')<label>Avancement<select name="status" data-task-status>@foreach(config('workspaces.task_statuses') as $value => $label)<option value="{{ $value }}" @selected($task->status === $value)>{{ $label }}</option>@endforeach</select></label><label data-blocked-field @if($task->status !== 'blocked') hidden @endif>Motif du blocage<textarea name="blocked_reason" rows="2" maxlength="5000" @required($task->status === 'blocked')>{{ $task->blocked_reason }}</textarea></label>@if(auth()->user()->checkPermissionTo('workspace.manage_tasks', 'web'))<label>Responsable<select name="assigned_to" required>@if(! $task->assigned_to)<option value="">Réaffecter la tâche</option>@endif @foreach($candidates as $candidate)<option value="{{ $candidate->id }}" @selected($task->assigned_to === $candidate->id)>{{ $candidate->name }}</option>@endforeach</select></label>@endif<button type="submit" class="ws-button ws-button-secondary">Enregistrer</button></form>@endif @endcan</article>
