    @foreach(['video_url' => 'Média de production', 'live_url' => 'Lien du direct'] as $field => $label)@if(filter_var($sequence->{$field}, FILTER_VALIDATE_URL) && in_array(strtolower(parse_url($sequence->{$field}, PHP_URL_SCHEME) ?? ''), ['http', 'https']))<a class="ws-link ws-media-link" href="{{ $sequence->{$field} }}" target="_blank" rel="noopener noreferrer">{{ $label }}</a>@endif @endforeach</article>@empty<p class="ws-empty">Ce sujet n’a pas encore été placé dans un conducteur.</p>@endforelse
